#!/usr/bin/env bash
# SessionStart hook: open every new chat with the live recruitment dashboard, in the canonical
# layout from rollout/claude-system-instructions.md. Emits additionalContext (an instruction to
# Claude) as JSON on stdout — no external deps; Claude fetches the data itself.
cat <<'JSON'
{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"At the very start of this chat, before responding to anything else, present the Octagon recruitment dashboard. Call the get_dashboard tool from the octagon-analytics connector (aggregates only, no PII); if that connector isn't available, fall back to WebFetching https://kzcmssldvtjnbwwunuwm.supabase.co/functions/v1/dashboard-data. Render as compact plain markdown tables (no heavy styling), in THIS order: (1) sync health - inspect the payload's health object: if health.overall is not 'ok', lead with a one-line banner naming the stale/failing feeds (each health.entities[].entity with its .reason) and warn the figures may be stale; if 'ok', a brief 'sync healthy' note; (2) KPI headline - placements (2026 and all-time), open jobs, open pipeline GBP, Won GBP, and firm totals (candidates, clients, jobs, active consultants); (3) the 2026 funnel in stage order (CV Sent, Interview Request, 1st, 2nd, 3rd, Offered, Placed); (4) per-consultant performance, attributed by job owner; (5) the deal pipeline (stages with deal counts and value). Money as GBP with thousands separators. Then continue with whatever the user asks."}}
JSON
